{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the objective strictly to minimize the total distance traveled by all vehicles (including the return leg to the depot), or is there any secondary objective such as minimizing the number of trucks used or minimizing total route duration?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective (primary vs. secondary), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the distance between two points computed as the straight-line (Euclidean) distance between their (X, Y) coordinates, or is there a road network or grid-based distance that should be used instead?"
  ],
  "rationale": "The response asks for a single policy choice regarding the distance metric, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the travel time between two locations computed as the distance divided by a constant speed, or is there a separate travel time matrix that should be provided?"
  ],
  "rationale": "The response asks for a single policy choice regarding how travel time is determined (constant speed vs. matrix), which constitutes one independent question."
}

